#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up purpose.openstuff.app on the home server (plan steps B4 and B5): Docker, GHCR,
# Supabase (database, sign-in, GitHub, email by Resend), the Cloudflare Tunnel, and deploy/.env.
# Run it on the home server, from anywhere: ./deploy/setup-wizard.sh

APP_URL=https://purpose.openstuff.app
SITE_URL=https://purpose.openstuff.dev
MAIL_DOMAIN=openstuff.app

# ask_valid KEY "Prompt" REGEX "Hint" [secret]: asks again until the value matches REGEX.
ask_valid() {
  local key="$1" prompt="$2" re="$3" hint="$4" secret="${5:-}"
  while :; do
    if [[ -n "$secret" ]]; then ask_secret "$key" "$prompt"; else ask "$key" "$prompt"; fi
    [[ "${!key}" =~ $re ]] && return 0
    warn "$hint"
  done
}

# supabase_auth JSON: PATCHes the project's auth config through the Management API. The token
# goes in a header file, so it never shows up in the process list.
supabase_auth() {
  local json="$1" what="$2" headers out code
  headers=$(mktemp); out=$(mktemp)
  printf 'Authorization: Bearer %s\nContent-Type: application/json\n' "$SUPABASE_ACCESS_TOKEN" > "$headers"
  while :; do
    code=$(printf '%s' "$json" | curl -sS -o "$out" -w '%{http_code}' -X PATCH -H "@$headers" \
      --data-binary @- "https://api.supabase.com/v1/projects/$SUPABASE_REF/config/auth" || echo 000)
    if [[ "$code" == 2* ]]; then
      printf '  %s✓ set%s %s in Supabase\n' "$GREEN" "$RESET" "$what"
      break
    fi
    warn "Supabase answered $code: $(head -c 300 "$out")"
    if ! confirm "Try again?"; then
      SKIPPED+=("Supabase: $what (Authentication settings in the dashboard)")
      break
    fi
  done
  rm -f "$headers" "$out"
}

# has_txt NAME PATTERN: whether a TXT record matches, when dig is installed.
has_txt() {
  command -v dig >/dev/null 2>&1 || return 2
  dig +short TXT "$1" | grep -q "$2"
}

run_wizard() {

TOTAL_STAGES=15
cd "$(dirname "${BASH_SOURCE[0]}")"

banner "OpenPurpose: home server and Supabase"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "This machine"
say "Checking the home server. Docker runs the stack as you, not as root."
missing=()
for cmd in docker curl jq; do command -v "$cmd" >/dev/null 2>&1 || missing+=("$cmd"); done
if (( ${#missing[@]} )); then
  warn "Missing: ${missing[*]}"
  step "Install Docker Engine with the compose plugin (not Docker Desktop):"
  open_url "https://docs.docker.com/engine/install/"
  step "And the rest, e.g. on Debian or Ubuntu: sudo apt install curl jq dnsutils"
  say "Then run this wizard again."
  exit 1
fi
if [[ "$(id -u)" == 0 ]]; then
  warn "You're root. Run this as your normal user, so the stack doesn't run as root."
  exit 1
fi
if ! docker info >/dev/null 2>&1; then
  warn "Your user can't talk to Docker yet. Run:  sudo usermod -aG docker $USER"
  say "Then log out and back in, and run this wizard again."
  exit 1
fi
docker compose version >/dev/null 2>&1 || { warn "'docker compose' doesn't work yet. Install the compose plugin, e.g. sudo apt install docker-compose-plugin"; exit 1; }
printf '  %s✓%s Docker %s, compose plugin, curl, jq\n' "$GREEN" "$RESET" "$(docker version -f '{{.Server.Version}}')"
if [[ ! -f "$ENV_FILE" ]]; then
  (umask 077 && cp .env.example "$ENV_FILE")
  printf '  %s✓ created%s %s/%s from .env.example (mode 600)\n' "$GREEN" "$RESET" "$PWD" "$ENV_FILE"
fi
chmod 600 "$ENV_FILE"
note "If your router can, put this server on its own network (a guest network or VLAN),"
note "away from the other devices at home."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub: pull the image"
ask OPENPURPOSE_IMAGE_TAG "Which release to run? (see CHANGELOG.md, e.g. 0.3.0)"
write_env OPENPURPOSE_IMAGE_TAG "$OPENPURPOSE_IMAGE_TAG"
IMAGE="ghcr.io/openstuff-dev/open-purpose:$OPENPURPOSE_IMAGE_TAG"
if docker pull -q "$IMAGE" >/dev/null 2>&1; then
  printf '  %s✓%s already able to pull %s\n' "$GREEN" "$RESET" "$IMAGE"
else
  say "The repository is private, so Docker needs a read-only GitHub token."
  open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=openpurpose-home-server"
  step "It's a classic token: GitHub's package registry doesn't take fine-grained ones."
  step "Leave only read:packages ticked, pick an expiry, click Generate token, copy it."
  ask GHCR_USER "Your GitHub username:"
  ask_secret GHCR_TOKEN "Paste the token (ghp_...):"
  printf '%s' "$GHCR_TOKEN" | docker login ghcr.io -u "$GHCR_USER" --password-stdin >/dev/null
  docker pull -q "$IMAGE" >/dev/null && printf '  %s✓ pulled%s %s\n' "$GREEN" "$RESET" "$IMAGE"
  note "Docker keeps the login in ~/.docker/config.json. Once the repo is public, run: docker logout ghcr.io"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: the production project"
say "A separate project for production, used for the database and for sign-in."
open_url "https://supabase.com/dashboard/new"
step "Name: openpurpose-prod. Region: Central EU (Frankfurt)."
step "Click Generate a password and save it in your password manager: you need it next."
step "Plan: Free pauses inactive projects and has no backups you can download;"
step "Pro (about \$25 a month) has daily backups. The backup service here runs either way."
step "Create the project. Its address is supabase.com/dashboard/project/<project ref>."
current_ref=$(_existing OPENPURPOSE_SUPABASE_URL | sed -nE 's#^https://([a-z0-9]+)\.supabase\.co$#\1#p' || true)
[[ -n "$current_ref" ]] && note "Current project ref: $current_ref"
while :; do
  read -e -r -p "  ${BOLD}Project ref (20 lowercase letters):${RESET} " -i "$current_ref" SUPABASE_REF
  [[ "$SUPABASE_REF" =~ ^[a-z0-9]{20}$ ]] && break
  warn "That doesn't look like a project ref, e.g. abcdefghijklmnopqrst"
done
write_env OPENPURPOSE_SUPABASE_URL "https://$SUPABASE_REF.supabase.co"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: database connection"
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF?showConnect=true"
step "Under Connection String, pick Session pooler (port 5432), not the transaction pooler"
step "(6543, which breaks the app's role switch) and not Direct (IPv6 only)."
step "Copy the URI and put your database password in place of [YOUR-PASSWORD]."
note "If the password has @ : / ? # or %, URL-encode it, or generate one without them."
ask_valid DATABASE_URL "Paste the connection string:" \
  '^postgres(ql)?://postgres\.[a-z0-9]{20}:[^@[:space:]]+@[a-z0-9.-]+\.pooler\.supabase\.com:5432/postgres$' \
  "Expected postgres://postgres.<ref>:<password>@<region>.pooler.supabase.com:5432/postgres" secret
write_env DATABASE_URL "$DATABASE_URL"
say "Checking the connection and the database user..."
if roles=$(docker run --rm -e DATABASE_URL postgres:17-alpine sh -c \
     'psql "$DATABASE_URL" -XAtc "select rolsuper, rolbypassrls, rolcreaterole from pg_roles where rolname = current_user"' 2>&1); then
  printf '  %s✓ connected%s (superuser|bypassrls|createrole = %s)\n' "$GREEN" "$RESET" "$roles"
  [[ "$roles" == *"|t" ]] || warn "This user can't create roles, so the first start can't create openpurpose_app."
  note "The user skips row-level security, so the app switches to openpurpose_app on every connection."
else
  warn "Couldn't connect: $roles"
  SKIPPED+=("Check DATABASE_URL in $ENV_FILE")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase: keys"
open_url "https://supabase.com/dashboard/project/$SUPABASE_REF/settings/api-keys"
step "Copy the Publishable key (sb_publishable_...). The app sends it to Supabase only."
ask_valid OPENPURPOSE_SUPABASE_KEY "Paste the publishable key:" '^sb_publishable_' \
  "The publishable key starts with sb_publishable_"
write_env OPENPURPOSE_SUPABASE_KEY "$OPENPURPOSE_SUPABASE_KEY"
write_env OPENPURPOSE_AUTH_PROVIDER supabase
write_env OPENPURPOSE_PUBLIC_URL "$APP_URL"
write_env OPENPURPOSE_SITE_URL "$SITE_URL"
write_env OPENPURPOSE_SIGNUP approval
write_env OPENPURPOSE_ORG_NAME OpenStuff
say ""
say "Next, this wizard sets sign-in, GitHub and email through Supabase's Management API."
open_url "https://supabase.com/dashboard/account/tokens"
step "Generate new token, name it openpurpose-wizard, copy it. Delete it when we're done."
note "It's kept in memory only, never written to $ENV_FILE."
ask_secret SUPABASE_ACCESS_TOKEN "Paste the access token (sbp_...):"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase: where sign-in links go"
say "Site URL $APP_URL, and sign-ins return to $APP_URL/api/auth/callback."
supabase_auth "$(jq -n --arg site "$APP_URL" --arg cb "$APP_URL/api/auth/callback" \
  '{site_url: $site, uri_allow_list: $cb}')" "Site URL and redirect URL"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GitHub: sign in with GitHub"
say "A separate OAuth app for production, owned by the openstuff-dev organization."
open_url "https://github.com/organizations/openstuff-dev/settings/applications/new"
step "Application name: OpenPurpose"
step "Homepage URL: $APP_URL"
step "Authorization callback URL: https://$SUPABASE_REF.supabase.co/auth/v1/callback"
step "Register application, copy the Client ID, then Generate a new client secret and copy it."
ask GITHUB_CLIENT_ID "Paste the Client ID:"
ask_secret GITHUB_CLIENT_SECRET "Paste the client secret:"
supabase_auth "$(jq -n --arg id "$GITHUB_CLIENT_ID" --arg secret "$GITHUB_CLIENT_SECRET" \
  '{external_github_enabled: true, external_github_client_id: $id, external_github_secret: $secret}')" \
  "the GitHub provider"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Resend: send from $MAIL_DOMAIN"
open_url "https://resend.com/domains"
step "Add domain: $MAIL_DOMAIN, region Ireland (eu-west-1)."
step "Let Resend add the records to Cloudflare if it offers to; otherwise add each record it"
step "lists (DKIM on resend._domainkey, MX and SPF on send) under Cloudflare › $MAIL_DOMAIN › DNS."
step "Click Verify and wait until the domain shows Verified."
pause "Press Enter once the domain is verified"
case $(has_txt "resend._domainkey.$MAIL_DOMAIN" 'p=' ; echo $?) in
  0) printf '  %s✓%s DKIM record found\n' "$GREEN" "$RESET" ;;
  1) warn "No DKIM record at resend._domainkey.$MAIL_DOMAIN yet. DNS can take a few minutes." ;;
  *) note "Install dig (dnsutils) to have this checked." ;;
esac
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Resend: Supabase sends through it"
open_url "https://resend.com/api-keys"
step "Create API key: name supabase-openpurpose, permission Sending access, domain $MAIL_DOMAIN."
ask_valid RESEND_API_KEY "Paste the API key (re_...):" '^re_' "Resend keys start with re_" secret
read -e -r -p "  ${BOLD}Send from:${RESET} " -i "noreply@$MAIL_DOMAIN" MAIL_FROM
supabase_auth "$(jq -n --arg from "$MAIL_FROM" --arg pass "$RESEND_API_KEY" '{
    smtp_admin_email: $from, smtp_sender_name: "OpenPurpose",
    smtp_host: "smtp.resend.com", smtp_port: "465", smtp_user: "resend", smtp_pass: $pass
  }')" "custom SMTP (Resend)"
# Supabase allows 30 emails an hour with custom SMTP until this is raised.
supabase_auth '{"rate_limit_email_sent": 100}' "the email limit (100 an hour; Authentication › Rate Limits)"
note "The app itself allows 20 sign-in links per visitor every 15 minutes."
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "DNS: DMARC for $MAIL_DOMAIN"
case $(has_txt "_dmarc.$MAIL_DOMAIN" 'v=DMARC1' ; echo $?) in
  0) printf '  %s✓%s %s already has a DMARC record:\n' "$GREEN" "$RESET" "$MAIL_DOMAIN"
     note "$(dig +short TXT "_dmarc.$MAIL_DOMAIN")" ;;
  *) say "DMARC tells mailboxes what to do with mail that fails SPF and DKIM."
     open_url "https://dash.cloudflare.com/?to=/:account/$MAIL_DOMAIN/dns/records"
     step "Add record: type TXT, name _dmarc, content:"
     step "  v=DMARC1; p=none; rua=mailto:<an address you read>"
     note "Start with p=none and read the reports. Once only Resend sends as $MAIL_DOMAIN,"
     note "change it to p=quarantine." ;;
esac
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Supabase: email wording"
say "Matches the app: the link has to be opened in the browser that asked for it."
read -r -d '' MAGIC_LINK <<'HTML' || true
<p>Here's your link to sign in to OpenPurpose:</p>
<p><a href="{{ .ConfirmationURL }}">Sign in to OpenPurpose</a></p>
<p>Open it in the same browser you asked for it in. It works once.</p>
<p>If you didn't ask for it, ignore this email.</p>
HTML
read -r -d '' CONFIRM <<'HTML' || true
<p>Here's your link to finish signing up for OpenPurpose:</p>
<p><a href="{{ .ConfirmationURL }}">Create your account</a></p>
<p>Open it in the same browser you asked for it in. It works once. A server admin then approves your account.</p>
<p>If you didn't ask for it, ignore this email.</p>
HTML
supabase_auth "$(jq -n --arg magic "$MAGIC_LINK" --arg confirm "$CONFIRM" '{
    mailer_subjects_magic_link: "Your OpenPurpose sign-in link",
    mailer_templates_magic_link_content: $magic,
    mailer_subjects_confirmation: "Finish signing up for OpenPurpose",
    mailer_templates_confirmation_content: $confirm
  }')" "the sign-in and sign-up emails"
open_url "https://supabase.com/dashboard/account/tokens"
step "That's all the wizard needs from Supabase: delete the openpurpose-wizard token now."
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: the tunnel"
open_url "https://one.dash.cloudflare.com/"
step "Networks › Tunnels › Create a tunnel › Cloudflared. Name: openpurpose-home."
step "On the install page, copy the token: the long eyJ... string after --token."
step "Don't run the install command: cloudflared runs in the stack here."
ask_valid TUNNEL_TOKEN "Paste the tunnel token:" '^eyJ[A-Za-z0-9_=-]+$' \
  "The token is the eyJ... string, without 'cloudflared service install'" secret
write_env TUNNEL_TOKEN "$TUNNEL_TOKEN"
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Cloudflare: the address"
step "Click Next to the public hostname (newer dashboards: Published application routes):"
step "  Subdomain purpose, domain openstuff.app, path empty"
step "  Service type HTTP, URL openpurpose:8080"
step "Save. Cloudflare adds the DNS record for purpose.openstuff.app itself."
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "The app and its backups"
if [[ -z "$(_existing OPENPURPOSE_BOOTSTRAP_TOKEN || true)" ]]; then
  write_env OPENPURPOSE_BOOTSTRAP_TOKEN "$(head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')"
else
  OPENPURPOSE_BOOTSTRAP_TOKEN=$(_existing OPENPURPOSE_BOOTSTRAP_TOKEN)
  note "Keeping the bootstrap token already in $ENV_FILE."
fi
write_env BACKUP_USER "$(id -u):$(id -g)"
mkdir -p backups && chmod 700 backups
ask TZ "Time zone for the 3:00 backup:"
write_env TZ "$TZ"
say ""
say "Optional: an email when a backup fails or doesn't run."
if confirm "Set up a heartbeat (Healthchecks.io)?"; then
  open_url "https://healthchecks.io/"
  step "Add a check: period 1 day, grace 2 hours. Copy its ping URL."
  ask_valid BACKUP_PING_URL "Paste the ping URL:" '^https://' "The ping URL starts with https://"
  write_env BACKUP_PING_URL "$BACKUP_PING_URL"
fi
say "Optional: a copy of every backup away from home."
if confirm "Copy backups to Cloudflare R2?"; then
  open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
  step "Create bucket: openpurpose-backups, location Europe. Keep public access off."
  step "Manage API tokens › Create API token: Object Read & Write, only this bucket."
  step "Copy the Access Key ID, the Secret Access Key and the S3 endpoint."
  ask R2_BUCKET "Bucket name:"
  ask_valid R2_ENDPOINT "S3 endpoint:" '^https://[a-f0-9]+\.(eu\.)?r2\.cloudflarestorage\.com$' \
    "Expected https://<account id>.r2.cloudflarestorage.com (or .eu.r2...)"
  ask R2_ACCESS_KEY_ID "Access Key ID:"
  ask_secret R2_SECRET_ACCESS_KEY "Secret Access Key:"
  for key in R2_BUCKET R2_ENDPOINT R2_ACCESS_KEY_ID R2_SECRET_ACCESS_KEY; do write_env "$key" "${!key}"; done
fi
pause

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Start it"
if confirm "Start the stack now (docker compose up -d)?"; then
  docker compose up -d --build
  say "Waiting for the app to be healthy..."
  health=""
  for _ in $(seq 60); do
    health=$(docker compose ps --format '{{.Health}}' openpurpose 2>/dev/null || true)
    [[ "$health" == healthy ]] && break
    sleep 3
  done
  if [[ "$health" == healthy ]]; then
    printf '  %s✓%s openpurpose is healthy\n' "$GREEN" "$RESET"
  else
    warn "Not healthy yet. Look at: docker compose logs openpurpose"
  fi
  if curl -fsS --max-time 10 "$APP_URL/api/health" >/dev/null 2>&1; then
    printf '  %s✓%s %s answers through the tunnel\n' "$GREEN" "$RESET" "$APP_URL"
  else
    warn "$APP_URL doesn't answer yet. Check the tunnel's status in Cloudflare."
  fi
  docker compose exec backup backup now || SKIPPED+=("First backup: docker compose exec backup backup now")
else
  SKIPPED+=("Start the stack: cd $PWD && docker compose up -d")
fi
say ""
say "Sign in at $APP_URL with this bootstrap token, then follow deploy/README.md"
say "to create your own token and clear this one:"
printf '\n    %s%s%s\n\n' "$BOLD" "$OPENPURPOSE_BOOTSTRAP_TOKEN" "$RESET"
step "Save $PWD/$ENV_FILE in your password manager: it starts the stack on any machine."
pause

finish
}

run_wizard "$@"; exit
